import math

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n-1)

def special_factorial(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer")

    result = 1
    for i in range(1, n+1):
        result *= factorial(i)

    return result

